const wire = (html: string) =>
  html
    // Sign in / CTA pills → the product's real login (same origin, no env var needed).
    .replace(/href="#" class="pill nav-login"/g, 'href="/login" class="pill nav-login"')
    .replace(/href="\/app"/g, 'href="/login?intent=start"')
    .replace(/class="close-cta" href="#"/g, 'class="close-cta" href="/login?intent=start"');

